--
-- Name: practice_exams; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.practice_exams (
    id integer NOT NULL,
    student_id integer,
    exam_number integer NOT NULL,
    turkce_dogru integer DEFAULT 0,
    turkce_yanlis integer DEFAULT 0,
    turkce_net numeric(5,2) DEFAULT 0,
    matematik_dogru integer DEFAULT 0,
    matematik_yanlis integer DEFAULT 0,
    matematik_net numeric(5,2) DEFAULT 0,
    fen_dogru integer DEFAULT 0,
    fen_yanlis integer DEFAULT 0,
    fen_net numeric(5,2) DEFAULT 0,
    sosyal_dogru integer DEFAULT 0,
    sosyal_yanlis integer DEFAULT 0,
    sosyal_net numeric(5,2) DEFAULT 0,
    ingilizce_dogru integer DEFAULT 0,
    ingilizce_yanlis integer DEFAULT 0,
    ingilizce_net numeric(5,2) DEFAULT 0,
    din_dogru integer DEFAULT 0,
    din_yanlis integer DEFAULT 0,
    din_net numeric(5,2) DEFAULT 0,
    lgs_score numeric(6,2) DEFAULT 0,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    teacher_note text,
    CONSTRAINT practice_exams_din_dogru_check CHECK (((din_dogru >= 0) AND (din_dogru <= 10))),
    CONSTRAINT practice_exams_din_yanlis_check CHECK (((din_yanlis >= 0) AND (din_yanlis <= 10))),
    CONSTRAINT practice_exams_exam_number_check CHECK (((exam_number >= 1) AND (exam_number <= 50))),
    CONSTRAINT practice_exams_fen_dogru_check CHECK (((fen_dogru >= 0) AND (fen_dogru <= 20))),
    CONSTRAINT practice_exams_fen_yanlis_check CHECK (((fen_yanlis >= 0) AND (fen_yanlis <= 20))),
    CONSTRAINT practice_exams_ingilizce_dogru_check CHECK (((ingilizce_dogru >= 0) AND (ingilizce_dogru <= 10))),
    CONSTRAINT practice_exams_ingilizce_yanlis_check CHECK (((ingilizce_yanlis >= 0) AND (ingilizce_yanlis <= 10))),
    CONSTRAINT practice_exams_matematik_dogru_check CHECK (((matematik_dogru >= 0) AND (matematik_dogru <= 20))),
    CONSTRAINT practice_exams_matematik_yanlis_check CHECK (((matematik_yanlis >= 0) AND (matematik_yanlis <= 20))),
    CONSTRAINT practice_exams_sosyal_dogru_check CHECK (((sosyal_dogru >= 0) AND (sosyal_dogru <= 10))),
    CONSTRAINT practice_exams_sosyal_yanlis_check CHECK (((sosyal_yanlis >= 0) AND (sosyal_yanlis <= 10))),
    CONSTRAINT practice_exams_turkce_dogru_check CHECK (((turkce_dogru >= 0) AND (turkce_dogru <= 20))),
    CONSTRAINT practice_exams_turkce_yanlis_check CHECK (((turkce_yanlis >= 0) AND (turkce_yanlis <= 20)))
);


